<?php
function librarySpecs():array{
 $text=fn($label,$required=true)=>['label'=>$label,'type'=>'text','required'=>$required];$choice=fn($label,$choices)=>['label'=>$label,'type'=>'select','required'=>true,'choices'=>$choices];$date=fn($label)=>['label'=>$label,'type'=>'date','required'=>true];$para=fn($label,$required=true)=>['label'=>$label,'type'=>'textarea','required'=>$required];
 return [
 'Current Awareness Service (CAS)'=>['updates'=>['label'=>'What type of updates would you like to receive?','type'=>'checks','required'=>true,'choices'=>['Newly acquired books','New journals/e-journals','New databases/e-resources','Research resources','Other']],'updates_other'=>$text('Other updates (specify if selected)',false),'topic'=>$text('Subject area / topic of interest')],
 'Electronic Resources Access'=>['resource'=>$text('Name of database / e-resource'),'access_purpose'=>$choice('Purpose of access',['Teaching','Research','Both']),'assistance'=>$choice('Do you require assistance with access?',['Yes','No'])],
 'Inter-Library Loan/Document Delivery'=>['resource_type'=>$choice('Type of resource',['Book','Journal article','Research paper','Report','Thesis/Dissertation','Other']),'title'=>$para('Title / article title'),'author'=>$text('Author'),'reference'=>$text('Year / volume / issue / DOI (if available)',false),'required_by'=>$date('Required by')],
 'Institutional Repository Service'=>['document_type'=>$choice('Type of document',['Research paper','Journal article','Conference paper','Report','Thesis/Dissertation','Other']),'title'=>$text('Title of document'),'repository_action'=>$choice('Action required',['Submit to repository','Update existing record','Access/retrieve document','Other'])],
 'New Book/Resource Recommendation'=>['title'=>$text('Title of book / resource'),'author'=>$text('Author'),'publisher'=>$text('Publisher (if known)',false),'publication_year'=>$text('Publication year (if known)',false),'isbn'=>$text('ISBN (if available)',false),'reason'=>$choice('Reason for recommendation',['Teaching','Research','Course requirement','Programme development','Other']),'course'=>$text('Course / module / programme')],
 'Course/Reading List Support'=>['course'=>$text('Course / module'),'semester'=>$choice('Semester',['I','II']),'reading_type'=>$choice('Type of reading list',['Essential Reading','Recommended Reading','Both']),'reading_list'=>$para('Reading list / required titles')],
 'Library Orientation'=>['topic'=>$choice('Preferred topic',['Introduction to Library Services','OPAC/Search Catalogue','E-books and E-journals','Online Databases','Research Skills','Referencing/Citation','Information Literacy','Other']),'preferred_date'=>$date('Preferred date'),'start_time'=>['label'=>'Preferred time','type'=>'time','required'=>true],'participants'=>['label'=>'Expected participants','type'=>'number','required'=>true]],
 'Library Class/Space Booking'=>['purpose'=>$para('Purpose of booking'),'preferred_date'=>$date('Preferred date'),'start_time'=>['label'=>'Start time','type'=>'time','required'=>true],'end_time'=>['label'=>'End time','type'=>'time','required'=>true],'participants'=>['label'=>'Number of participants','type'=>'number','required'=>true],'requirements'=>$para('Special requirements: computers, projector, internet, group space, etc.',false)],
 'Other Library Service'=>['details'=>$para('Describe the service required')]
 ];
}
function validateLibrary(array $p):array{
 $service=required($p,'service');$specs=librarySpecs();attRequire(isset($specs[$service]),'Select a valid library service.');$programme=required($p,'programme');attRequire(in_array($programme,array_merge(programmes(),departments()),true),'Select a valid programme / department.');$out=['service'=>$service,'programme'=>$programme,'contact_number'=>trim($p['contact_number']??'')];
 foreach($specs[$service]as $key=>$spec){$v=$p[$key]??'';if($spec['type']==='checks'){attRequire(is_array($v)&&count($v)>0&&!array_diff($v,$spec['choices']),'Select at least one valid update type.');$v=implode(', ',array_unique($v));}else{$v=trim((string)$v);if($spec['required'])required($p,$key);if($v!==''&&isset($spec['choices']))attRequire(in_array($v,$spec['choices'],true),'Invalid '.$spec['label']);if($v!==''&&$spec['type']==='date')attRequire(dateValid($v),'Invalid date.');if($v!==''&&$spec['type']==='time')attRequire(timeValid($v),'Invalid time.');if($v!==''&&$spec['type']==='number')attRequire(ctype_digit($v)&&(int)$v>0,'Participants must be a positive number.');}attRequire(mb_strlen($v)<=10000,'Field too long.');$out[$key]=$v;}
 if($service==='Current Awareness Service (CAS)'&&in_array('Other',$p['updates']??[],true))required($p,'updates_other');
 if(isset($out['end_time']))attRequire($out['end_time']>$out['start_time'],'End time must be after start time.');
 if($service==='Institutional Repository Service'&&$out['repository_action']==='Submit to repository')attRequire(($_FILES['attachment']['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_OK,'Upload the document to submit to the repository.');
 $out['comments']=trim($p['comments']??'');return $out;
}
function renderLibraryFields():void{foreach(librarySpecs()as $service=>$defs){echo '<fieldset class="full service-fields" data-service="'.e($service).'" hidden disabled><legend>'.e($service).'</legend><div class="form-grid">';foreach($defs as $key=>$spec){if($spec['type']==='checks'){echo '<div><p>'.e($spec['label']).'</p>';foreach($spec['choices']as $choice)echo '<label class="check"><input type="checkbox" name="'.e($key).'[]" value="'.e($choice).'">'.e($choice).'</label>';echo '</div>';}else field($key,$spec['label'],$spec['type'],$spec['choices']??[],$spec['required']);}echo '</div></fieldset>';}}
